from pathlib import Path
import json,ast
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'docs/permissions-audit-round1-20261028'
def loc(file,fn):
 p=ROOT/file
 if p.suffix!='.py':return file
 for node in ast.walk(ast.parse(p.read_text())):
  if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)) and node.name==fn:return f'{file}:{node.lineno}'
 return file
